package com.prem.gateway; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.config.web.server.ServerHttpSecurity; import org.springframework.security.web.server.SecurityWebFilterChain; @Configuration public class SecurityConfig { @Bean SecurityWebFilterChain securityWebFilterChain(ServerHttpSecurity http){return http.csrf(ServerHttpSecurity.CsrfSpec::disable).authorizeExchange(e->e.pathMatchers("/actuator/health","/fallback/**").permitAll().pathMatchers("/api/admin/**").hasRole("ADMIN").pathMatchers("/api/**").hasAnyRole("USER","ADMIN").anyExchange().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(new KeycloakRoleConverter()))).build();} }
